import re


# Minimal stand-ins for Django pieces so the logic runs without a project/settings.
class User:
    def __init__(self, username, email):
        self.username = username
        self.email = email


class Messages:
    def __init__(self):
        self.stored = []

    def success(self, request, text):
        self.stored.append(('success', text))

    def error(self, request, text):
        self.stored.append(('error', text))


messages = Messages()


def redirect(name):
    return {'status': 302, 'url': name}


def render(request, template, context):
    return {'status': 200, 'template': template, 'context': context}


class Request:
    def __init__(self, method='GET', POST=None):
        self.method = method
        self.POST = POST or {}


class RegisterForm:
    """Mirrors UserCreationForm + email (required) + bio (optional)."""

    def __init__(self, data=None):
        self.data = data
        self.errors = {}
        self.saved_user = None

    def is_valid(self):
        if self.data is None:
            return False
        d = self.data
        if not d.get('username'):
            self.errors['username'] = 'Required.'
        if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', d.get('email', '')):
            self.errors['email'] = 'Enter a valid email address.'
        if len(d.get('password1', '')) < 8:
            self.errors['password1'] = 'Password too short.'
        if d.get('password1') != d.get('password2'):
            self.errors['password2'] = 'Passwords do not match.'
        return not self.errors

    def save(self):
        self.saved_user = User(self.data['username'], self.data['email'])
        return self.saved_user


def register(request):
    if request.method == 'POST':
        form = RegisterForm(request.POST)
        if form.is_valid():
            user = form.save()
            messages.success(request, f'Welcome, {user.username}! Please log in.')
            return redirect('login')
        else:
            messages.error(request, 'Please fix the errors below.')
    else:
        form = RegisterForm()
    return render(request, 'register.html', {'form': form})


# GET shows the form
assert register(Request('GET'))['status'] == 200

# Invalid POST re-renders with an error message
bad = register(Request('POST', {'username': 'ann', 'email': 'nope',
                                'password1': 'x', 'password2': 'y'}))
assert bad['status'] == 200 and messages.stored[-1][0] == 'error'

# Valid POST redirects to login with a success message
good = register(Request('POST', {'username': 'ann', 'email': 'ann@example.com',
                                 'password1': 'S3cure-pass!', 'password2': 'S3cure-pass!',
                                 'bio': 'Hi'}))
if good['status'] == 302 and good['url'] == 'login' and messages.stored[-1][0] == 'success':
    print('Successful registration redirects to login with success message')
